const SYNC_CONFIG={databaseUrl:"",enabled:false};const SYNCED_TABLES=["worshipLog","takbeer","mushaf","fasting","badges","history","zakatCalc"];const SyncState={status:"offline",lastSync:null,userId:null};async function enableCloudSync(){if(!SYNC_CONFIG.databaseUrl){showSyncMessage("المزامنة السحابية غير مُعدّة بعد. تحتاج لإعداد Dexie Cloud أولاً.","info");showSyncSetupGuide();return}try{await loadDexieCloudAddon();SyncState.status="syncing";updateSyncUI();if(window.ZadDB?.cloud){await window.ZadDB.cloud.configure({databaseUrl:SYNC_CONFIG.databaseUrl,requireAuth:false})}SYNC_CONFIG.enabled=true;localStorage.setItem("zad_sync_enabled","1");SyncState.status="synced";SyncState.lastSync=Date.now();updateSyncUI();showSyncMessage("✅ تم تفعيل المزامنة — بياناتك الآن محفوظة سحابياً","success")}catch(err){SyncState.status="error";updateSyncUI();showSyncMessage("تعذّر تفعيل المزامنة — حاول لاحقاً","error");console.error("[Sync]",err)}}window.enableCloudSync=enableCloudSync;async function disableCloudSync(){SYNC_CONFIG.enabled=false;localStorage.removeItem("zad_sync_enabled");SyncState.status="offline";updateSyncUI();showSyncMessage("تم إيقاف المزامنة — بياناتك تبقى محفوظة على هذا الجهاز","info")}window.disableCloudSync=disableCloudSync;function loadDexieCloudAddon(){return new Promise((resolve,reject)=>{if(window.DexieCloud){resolve();return}const s=document.createElement("script");s.src="https://cdn.jsdelivr.net/npm/dexie-cloud-addon@1.0.0/dist/umd/dexie-cloud-addon.min.js";s.onload=resolve;s.onerror=()=>reject(new Error("فشل تحميل dexie-cloud"));document.head.appendChild(s)})}function renderSyncPanel(){const container=document.getElementById("sync-panel");if(!container)return;const enabled=localStorage.getItem("zad_sync_enabled")==="1";container.innerHTML=`\n    <div class="sync-card">\n      <div class="sync-header">\n        <div class="sync-icon">${enabled?"☁️":"📴"}</div>\n        <div class="sync-info">\n          <div class="sync-title">المزامنة السحابية</div>\n          <div class="sync-status-text" id="sync-status-text">\n            ${enabled?"مفعّلة — بياناتك تُزامَن بين أجهزتك":"معطّلة — بياناتك على هذا الجهاز فقط"}\n          </div>\n        </div>\n      </div>\n\n      <div class="sync-explain">\n        المزامنة <strong>اختيارية تماماً</strong>. التطبيق يعمل بالكامل بدون إنترنت وبدون حساب.\n        عند التفعيل، تُزامَن متابعتك (الحصاد، الأوسمة، التقدم) بين أجهزتك.\n        <br><br>\n        🔒 <strong>الخصوصية:</strong> إعداداتك الشخصية وملفك الشخصي يبقيان على جهازك ولا يُرفعان.\n      </div>\n\n      <div class="sync-tables">\n        <div class="sync-tables-title">ما يُزامَن:</div>\n        <div class="sync-tables-list">سجل العبادات · التكبير · الختمة · الصيام · الأوسمة · حسابات الزكاة</div>\n      </div>\n\n      ${enabled?`<button class="btn btn-ghost" onclick="disableCloudSync()" style="width:100%">إيقاف المزامنة</button>`:`<button class="btn btn-primary" onclick="enableCloudSync()" style="width:100%">تفعيل المزامنة بين الأجهزة</button>`}\n    </div>`}function updateSyncUI(){const statusText=document.getElementById("sync-status-text");if(statusText){const messages={offline:"معطّلة — بياناتك على هذا الجهاز فقط",syncing:"⏳ جارٍ المزامنة...",synced:"✅ مُزامَنة — آخر تحديث الآن",error:"⚠️ خطأ في المزامنة"};statusText.textContent=messages[SyncState.status]||""}}function showSyncMessage(msg,type){if(typeof showToast==="function")showToast(msg)}function showSyncSetupGuide(){const modal=document.createElement("div");modal.style.cssText="position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px";modal.innerHTML=`\n    <div style="background:var(--card,#fff);border-radius:20px;padding:24px;max-width:420px;max-height:80vh;overflow:auto">\n      <h3 style="margin:0 0 16px;font-size:17px">إعداد المزامنة السحابية</h3>\n      <div style="font-size:14px;line-height:1.9;color:var(--ink)">\n        لتفعيل المزامنة، يحتاج المطوّر لإعداد Dexie Cloud (مجاني حتى 100 مستخدم):\n        <ol style="padding-right:20px;margin:12px 0">\n          <li>سجّل في <strong>dexie.cloud</strong></li>\n          <li>أنشئ قاعدة بيانات جديدة (مجاني)</li>\n          <li>انسخ الـ databaseUrl</li>\n          <li>ضعه في <code>SYNC_CONFIG.databaseUrl</code> داخل <code>js/sync-module.js</code></li>\n        </ol>\n        البديل: Firebase Firestore لو احتجت Real-time أقوى — لكن Dexie Cloud أبسط\n        لأنه امتداد مباشر لقاعدة البيانات الحالية.\n      </div>\n      <button onclick="this.closest('[style*=fixed]').remove()" \n              class="btn btn-primary" style="width:100%;margin-top:16px">فهمت</button>\n    </div>`;document.body.appendChild(modal)}window.showSyncSetupGuide=showSyncSetupGuide;const SYNC_CSS=`\n.sync-card { background: var(--card, #fff); border: 1.5px solid var(--border, #ddd); border-radius: 18px; padding: 20px; }\n.sync-header { display: flex; gap: 14px; align-items: center; margin-bottom: 16px; }\n.sync-icon { font-size: 36px; }\n.sync-title { font-size: 17px; font-weight: 800; }\n.sync-status-text { font-size: 13px; color: var(--muted, #888); margin-top: 2px; }\n.sync-explain { font-size: 13px; line-height: 1.8; color: var(--ink); background: rgba(0,0,0,.03); padding: 14px; border-radius: 12px; margin-bottom: 14px; }\n.sync-tables { margin-bottom: 16px; }\n.sync-tables-title { font-size: 13px; font-weight: 700; margin-bottom: 4px; }\n.sync-tables-list { font-size: 13px; color: var(--muted, #888); line-height: 1.6; }\n`;function injectSyncCSS(){if(document.getElementById("sync-css"))return;const s=document.createElement("style");s.id="sync-css";s.textContent=SYNC_CSS;document.head.appendChild(s)}document.addEventListener("DOMContentLoaded",()=>{if(document.getElementById("sync-panel")){injectSyncCSS();renderSyncPanel();if(localStorage.getItem("zad_sync_enabled")==="1"&&SYNC_CONFIG.databaseUrl){SYNC_CONFIG.enabled=true}console.log("[SyncModule] ✅ موديول المزامنة جاهز")}});window.SYNC_CONFIG=SYNC_CONFIG;window.SyncState=SyncState;